mapper.select:
select fq.id, fq.factory_id, factory.factory_name, fq.style_id, fs.style_number, fq.category_id, fjc.category, fq.price, fs.image_path, fq.created_date, fq.flag from factory_piece_rate fq left join factory on fq.factory_id = factory.id and factory.flag = 0 left join factory_style fs on fq.style_id = fs.id and fs.flag = 0 left join job_category fjc on fq.category_id = fjc.id and fjc.flag = 0 where fq.flag = #{flag}
and fq.factory_id = #{factoryId}
and fs.style_number like CONCAT('%', #{styleNumber}, '%')
and fq.category_id = #{categoryId}
order by factory.factory_name desc

select fq.id, fq.factory_id, fq.style_id, fs.style_number, fq.category_id, fjc.category, fq.price from factory_piece_rate fq left join factory_style fs on fq.style_id = fs.id and fs.flag = 0 left join job_category fjc on fq.category_id = fjc.id and fjc.flag = 0 where fq.flag = #{flag}
and fq.factory_id = #{factoryId}
order by fs.style_number asc, fjc.category asc
